        def __init__(
            self,
            tagName: Union[str, TagName],
            subsystem: Union[str, Subsystem],
            tagDescription: Optional[Union[str, TagDescription]] = None,
            safeStateOfDevice: Optional[Union[str, SafeStateOfDevice]] = None,
            equipmentType: Optional[Union[str, EquipmentType]] = None,
            referenceToTagGroup: Optional[
                Iterable[Union[str, ReferenceToTagGroup]]
            ] = None,
            id_short: Optional[str] = r"TagInformation",
            display_name: Optional[MultiLanguageNameType] = MultiLanguageNameType(
                dict_={r"en": r"tag information"}
            ),
            category: Optional[str] = None,
            description: Optional[MultiLanguageTextType] = MultiLanguageTextType(
                dict_={
                    r"en": r"gives relevant information about the tag that the device represents"
                }
            ),
            semantic_id: Optional[Reference] = ExternalReference(
                key=(
                    Key(
                        type_=KeyTypes.GLOBAL_REFERENCE,
                        value=r"https://admin-shell.io/idta/cds/TagInformation/1",
                    ),
                ),
                referred_semantic_id=None,
            ),
            qualifier: Iterable[Qualifier] = None,
            extension: Iterable[Extension] = (),
            supplemental_semantic_id: Iterable[Reference] = (),
            embedded_data_specifications: Iterable[EmbeddedDataSpecification] = None,
        ):

            if qualifier is None:
                qualifier = (
                    Qualifier(
                        type_=r"SMT/Cardinality",
                        value_type=str,
                        value=r"One",
                        value_id=None,
                        kind=QualifierKind.TEMPLATE_QUALIFIER,
                        semantic_id=ExternalReference(
                            key=(
                                Key(
                                    type_=KeyTypes.GLOBAL_REFERENCE,
                                    value=r"https://admin-shell.io/SubmodelTemplates/Cardinality/1/0",
                                ),
                            ),
                            referred_semantic_id=None,
                        ),
                        supplemental_semantic_id=(),
                    ),
                )

            if embedded_data_specifications is None:
                embedded_data_specifications = []

            # Build a submodel element if a raw value was passed in the argument
            if tagName and not isinstance(tagName, SubmodelElement):
                tagName = self.TagName(tagName)

            # Build a submodel element if a raw value was passed in the argument
            if tagDescription and not isinstance(tagDescription, SubmodelElement):
                tagDescription = self.TagDescription(tagDescription)

            # Build a submodel element if a raw value was passed in the argument
            if subsystem and not isinstance(subsystem, SubmodelElement):
                subsystem = self.Subsystem(subsystem)

            # Build a submodel element if a raw value was passed in the argument
            if safeStateOfDevice and not isinstance(safeStateOfDevice, SubmodelElement):
                safeStateOfDevice = self.SafeStateOfDevice(safeStateOfDevice)

            # Build a submodel element if a raw value was passed in the argument
            if equipmentType and not isinstance(equipmentType, SubmodelElement):
                equipmentType = self.EquipmentType(equipmentType)

            # Build a list of submodel elements if a raw values were passed in the argument
            if referenceToTagGroup and all(
                [isinstance(i, str) for i in referenceToTagGroup]
            ):
                referenceToTagGroup = [
                    self.ReferenceToTagGroup(i) for i in referenceToTagGroup
                ]

            # Add all passed/initialized submodel elements to a single list
            embedded_submodel_elements = []
            for se_arg in [
                tagName,
                tagDescription,
                subsystem,
                safeStateOfDevice,
                equipmentType,
                referenceToTagGroup,
            ]:
                if se_arg is None:
                    continue
                elif isinstance(se_arg, SubmodelElement):
                    embedded_submodel_elements.append(se_arg)
                elif isinstance(se_arg, Iterable):
                    for n, element in enumerate(se_arg):
                        element.id_short = f"{element.id_short}{n}"
                        embedded_submodel_elements.append(element)
                else:
                    raise TypeError(
                        f"Unknown type of value in submodel_element_args: {type(se_arg)}"
                    )

            super().__init__(
                value=embedded_submodel_elements,
                id_short=id_short,
                display_name=display_name,
                category=category,
                description=description,
                semantic_id=semantic_id,
                qualifier=qualifier,
                extension=extension,
                supplemental_semantic_id=supplemental_semantic_id,
                embedded_data_specifications=embedded_data_specifications,
            )

