                def __init__(
                    self,
                    tripPointName: Union[str, TripPointName],
                    tripPointValue: Union[Decimal, TripPointValue],
                    hysteresisOfTripPoint: Optional[
                        Union[Decimal, HysteresisOfTripPoint]
                    ] = None,
                    tripDeadTime: Optional[Union[Decimal, TripDeadTime]] = None,
                    referenceToAlarm: Optional[
                        Union[Reference, ReferenceToAlarm]
                    ] = None,
                    id_short: Optional[str] = r"TripPoint",
                    display_name: Optional[
                        MultiLanguageNameType
                    ] = MultiLanguageNameType(dict_={r"en": r"Trip point"}),
                    category: Optional[str] = None,
                    description: Optional[
                        MultiLanguageTextType
                    ] = MultiLanguageTextType(
                        dict_={r"en": r"gives information about the device diagnostics"}
                    ),
                    semantic_id: Optional[Reference] = ExternalReference(
                        key=(
                            Key(
                                type_=KeyTypes.GLOBAL_REFERENCE,
                                value=r"https://admin-shell.io/idta/cds/TripPoint/1",
                            ),
                        ),
                        referred_semantic_id=None,
                    ),
                    qualifier: Iterable[Qualifier] = None,
                    extension: Iterable[Extension] = (),
                    supplemental_semantic_id: Iterable[Reference] = (),
                    embedded_data_specifications: Iterable[
                        EmbeddedDataSpecification
                    ] = None,
                ):

                    if qualifier is None:
                        qualifier = (
                            Qualifier(
                                type_=r"SMT/Cardinality",
                                value_type=str,
                                value=r"ZeroToMany",
                                value_id=None,
                                kind=QualifierKind.TEMPLATE_QUALIFIER,
                                semantic_id=ExternalReference(
                                    key=(
                                        Key(
                                            type_=KeyTypes.GLOBAL_REFERENCE,
                                            value=r"https://admin-shell.io/SubmodelTemplates/Cardinality/1/0",
                                        ),
                                    ),
                                    referred_semantic_id=None,
                                ),
                                supplemental_semantic_id=(),
                            ),
                        )

                    if embedded_data_specifications is None:
                        embedded_data_specifications = []

                    # Build a submodel element if a raw value was passed in the argument
                    if tripPointName and not isinstance(tripPointName, SubmodelElement):
                        tripPointName = self.TripPointName(tripPointName)

                    # Build a submodel element if a raw value was passed in the argument
                    if tripPointValue and not isinstance(
                        tripPointValue, SubmodelElement
                    ):
                        tripPointValue = self.TripPointValue(tripPointValue)

                    # Build a submodel element if a raw value was passed in the argument
                    if hysteresisOfTripPoint and not isinstance(
                        hysteresisOfTripPoint, SubmodelElement
                    ):
                        hysteresisOfTripPoint = self.HysteresisOfTripPoint(
                            hysteresisOfTripPoint
                        )

                    # Build a submodel element if a raw value was passed in the argument
                    if tripDeadTime and not isinstance(tripDeadTime, SubmodelElement):
                        tripDeadTime = self.TripDeadTime(tripDeadTime)

                    # Build a submodel element if a raw value was passed in the argument
                    if referenceToAlarm and not isinstance(
                        referenceToAlarm, SubmodelElement
                    ):
                        referenceToAlarm = self.ReferenceToAlarm(referenceToAlarm)

                    # Add all passed/initialized submodel elements to a single list
                    embedded_submodel_elements = []
                    for se_arg in [
                        tripPointName,
                        tripPointValue,
                        hysteresisOfTripPoint,
                        tripDeadTime,
                        referenceToAlarm,
                    ]:
                        if se_arg is None:
                            continue
                        elif isinstance(se_arg, SubmodelElement):
                            embedded_submodel_elements.append(se_arg)
                        elif isinstance(se_arg, Iterable):
                            for n, element in enumerate(se_arg):
                                element.id_short = f"{element.id_short}{n}"
                                embedded_submodel_elements.append(element)
                        else:
                            raise TypeError(
                                f"Unknown type of value in submodel_element_args: {type(se_arg)}"
                            )

                    super().__init__(
                        value=embedded_submodel_elements,
                        id_short=id_short,
                        display_name=display_name,
                        category=category,
                        description=description,
                        semantic_id=semantic_id,
                        qualifier=qualifier,
                        extension=extension,
                        supplemental_semantic_id=supplemental_semantic_id,
                        embedded_data_specifications=embedded_data_specifications,
                    )

