        def __init__(
            self,
            lambdaDUDesign: Union[float, LambdaDUDesign],
            safeFailureFractionDesign: Union[Decimal, SafeFailureFractionDesign],
            diagnosticCoverageDesign: Union[Decimal, DiagnosticCoverageDesign],
            dataSource: Iterable[Union[str, DataSource]],
            meanTimeBetweenFailures: Optional[
                Union[Decimal, MeanTimeBetweenFailures]
            ] = None,
            lambdaDDDesign: Optional[Union[float, LambdaDDDesign]] = None,
            lambdaSUDesign: Optional[Union[float, LambdaSUDesign]] = None,
            lambdaSDDesign: Optional[Union[float, LambdaSDDesign]] = None,
            beta: Optional[Union[Decimal, Beta]] = None,
            id_short: Optional[str] = r"ReliabilityDataDesign",
            display_name: Optional[MultiLanguageNameType] = MultiLanguageNameType(
                dict_={r"en": r"reliability data design"}
            ),
            category: Optional[str] = None,
            description: Optional[MultiLanguageTextType] = MultiLanguageTextType(
                dict_={
                    r"en": r"reliability data parameter(s) with design data value(s)"
                }
            ),
            semantic_id: Optional[Reference] = ExternalReference(
                key=(
                    Key(
                        type_=KeyTypes.GLOBAL_REFERENCE,
                        value=r"https://admin-shell.io/idta/cds/ReliabilityDataDesign/1",
                    ),
                ),
                referred_semantic_id=None,
            ),
            qualifier: Iterable[Qualifier] = None,
            extension: Iterable[Extension] = (),
            supplemental_semantic_id: Iterable[Reference] = (),
            embedded_data_specifications: Iterable[EmbeddedDataSpecification] = None,
        ):

            if qualifier is None:
                qualifier = (
                    Qualifier(
                        type_=r"SMT/Cardinality",
                        value_type=str,
                        value=r"One",
                        value_id=None,
                        kind=QualifierKind.TEMPLATE_QUALIFIER,
                        semantic_id=ExternalReference(
                            key=(
                                Key(
                                    type_=KeyTypes.GLOBAL_REFERENCE,
                                    value=r"https://admin-shell.io/SubmodelTemplates/Cardinality/1/0",
                                ),
                            ),
                            referred_semantic_id=None,
                        ),
                        supplemental_semantic_id=(),
                    ),
                )

            if embedded_data_specifications is None:
                embedded_data_specifications = []

            # Build a submodel element if a raw value was passed in the argument
            if meanTimeBetweenFailures and not isinstance(
                meanTimeBetweenFailures, SubmodelElement
            ):
                meanTimeBetweenFailures = self.MeanTimeBetweenFailures(
                    meanTimeBetweenFailures
                )

            # Build a submodel element if a raw value was passed in the argument
            if lambdaDUDesign and not isinstance(lambdaDUDesign, SubmodelElement):
                lambdaDUDesign = self.LambdaDUDesign(lambdaDUDesign)

            # Build a submodel element if a raw value was passed in the argument
            if lambdaDDDesign and not isinstance(lambdaDDDesign, SubmodelElement):
                lambdaDDDesign = self.LambdaDDDesign(lambdaDDDesign)

            # Build a submodel element if a raw value was passed in the argument
            if lambdaSUDesign and not isinstance(lambdaSUDesign, SubmodelElement):
                lambdaSUDesign = self.LambdaSUDesign(lambdaSUDesign)

            # Build a submodel element if a raw value was passed in the argument
            if lambdaSDDesign and not isinstance(lambdaSDDesign, SubmodelElement):
                lambdaSDDesign = self.LambdaSDDesign(lambdaSDDesign)

            # Build a submodel element if a raw value was passed in the argument
            if beta and not isinstance(beta, SubmodelElement):
                beta = self.Beta(beta)

            # Build a submodel element if a raw value was passed in the argument
            if safeFailureFractionDesign and not isinstance(
                safeFailureFractionDesign, SubmodelElement
            ):
                safeFailureFractionDesign = self.SafeFailureFractionDesign(
                    safeFailureFractionDesign
                )

            # Build a submodel element if a raw value was passed in the argument
            if diagnosticCoverageDesign and not isinstance(
                diagnosticCoverageDesign, SubmodelElement
            ):
                diagnosticCoverageDesign = self.DiagnosticCoverageDesign(
                    diagnosticCoverageDesign
                )

            # Build a list of submodel elements if a raw values were passed in the argument
            if dataSource and all([isinstance(i, str) for i in dataSource]):
                dataSource = [self.DataSource(i) for i in dataSource]

            # Add all passed/initialized submodel elements to a single list
            embedded_submodel_elements = []
            for se_arg in [
                meanTimeBetweenFailures,
                lambdaDUDesign,
                lambdaDDDesign,
                lambdaSUDesign,
                lambdaSDDesign,
                beta,
                safeFailureFractionDesign,
                diagnosticCoverageDesign,
                dataSource,
            ]:
                if se_arg is None:
                    continue
                elif isinstance(se_arg, SubmodelElement):
                    embedded_submodel_elements.append(se_arg)
                elif isinstance(se_arg, Iterable):
                    for n, element in enumerate(se_arg):
                        element.id_short = f"{element.id_short}{n}"
                        embedded_submodel_elements.append(element)
                else:
                    raise TypeError(
                        f"Unknown type of value in submodel_element_args: {type(se_arg)}"
                    )

            super().__init__(
                value=embedded_submodel_elements,
                id_short=id_short,
                display_name=display_name,
                category=category,
                description=description,
                semantic_id=semantic_id,
                qualifier=qualifier,
                extension=extension,
                supplemental_semantic_id=supplemental_semantic_id,
                embedded_data_specifications=embedded_data_specifications,
            )

